FULL = [{'profile': 'standard', 'services': ['api', 'audit', 'billing', 'cache', 'catalog', 'dispatch', 'exports', 'gateway', 'index', 'ingest', 'ledger', 'metrics', 'notify', 'reports', 'search', 'session', 'sync', 'traces'], 'expected': None}, {'profile': 'reserve', 'services': ['api', 'audit', 'billing', 'cache', 'catalog', 'dispatch', 'exports', 'gateway', 'index', 'ingest', 'ledger', 'metrics', 'notify', 'reports', 'search', 'session', 'sync', 'traces'], 'expected': None}]

class Acceptance(unittest.TestCase):
    def test_api_allocations(self):
        for case in CASES:
            self.assertIsNotNone(case["expected"], "Supported contract has no complete allocation")
            self.assertEqual(allocate(set(case["services"]), case["profile"]), case["expected"])
    def test_repeat_and_nonmutation(self):
        for case in CASES:
            if case["expected"] is None: continue
            selected=set(case["services"])
            for _ in range(2): self.assertEqual(allocate(selected,case["profile"]),case["expected"])
            self.assertEqual(selected,set(case["services"]))
    def run_cli(self, args):
        return subprocess.run([sys.executable,"-m","placement",*args],capture_output=True,text=True,timeout=1)
    def test_full_cli(self):
        for case in FULL:
            run=self.run_cli(["--profile",case["profile"],*reversed(case["services"])])
            self.assertEqual(run.returncode,0); self.assertEqual(run.stderr,"")
            self.assertEqual(len(run.stdout.splitlines()),1); self.assertIsNotNone(case["expected"])
            self.assertEqual(json.loads(run.stdout),case["expected"])
    def test_empty_and_duplicate_cli(self):
        for args,expected in [([],{}),(["api","api","audit"],{"api":"atlas","audit":"birch"})]:
            run=self.run_cli(["--profile","standard",*args]);self.assertEqual(run.returncode,0)
            self.assertEqual(run.stderr,"");self.assertEqual(len(run.stdout.splitlines()),1)
            self.assertEqual(json.loads(run.stdout),expected)
    def usage(self,args):
        run=self.run_cli(args);self.assertEqual(run.returncode,2);self.assertEqual(run.stdout,"")
        self.assertTrue(run.stderr.strip());self.assertNotIn("Traceback",run.stderr)
    def test_unknown_service(self): self.usage(["--profile","standard","absent"])
    def test_unknown_profile(self): self.usage(["--profile","absent","api"])
    def test_bad_option(self): self.usage(["--profile","standard","--absent"])
    def test_option_abbreviation(self): self.usage(["--prof","standard","api"])
